head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p.data > M > set]<br/>여러 개의 DataList 또는 DataMap 에 데이터를 할당합니다.",
    "validation" : [
        "dataType(필수) 파라미터로 할당 데이터의 유형을 'JSON', 'ARRAY', 'XML' 중 하나로 설정할 수 있어야 합니다.",
        "dataType 이 'JSON' 인 경우 데이터를 JSON 객체로 할당해야 합니다.",
        "dataType 이 'ARRAY' 인 경우 데이터를 Array 로 할당해야 합니다.",
        "dataType 이 'XML' 인 경우 데이터를 XML 로 할당해야 합니다.",
        "data(필수) 파라미터로 dataType 에 설정한 유형과 일치하는 데이터를 설정할 수 있어야 합니다.",
        "dcInfo(선택) 파라미터로 데이터를 할당할 DataList 또는 DataMap 의 정보를 ID 배열로 설정할 수 있어야 합니다.",
        "dcInfo(선택) 파라미터로 데이터를 할당할 DataList 또는 DataMap 의 정보를 JSON 객체 배열로 설정할 수 있어야 합니다.",
        "dcInfo(선택) 파라미터를 설정하지 않으면 data 파라미터의 키값을 참조하여 데이터가 할당되어야 합니다.",
        "data 파라미터의 키값과 일치하는 DataCollection 이 없는 경우(undefined_data) 해당 키는 무시되어야 합니다.",
        "LinkedDataList, AliasDataList, AliasDataMap 은 직접 할당 대상에서 제외되며, 참조된 원본 DataList 또는 DataMap 에 할당해야 합니다.",
        "dcInfo.id(필수) 로 데이터가 설정될 DataList 또는 DataMap 의 ID 를 설정할 수 있어야 합니다.",
        "dcInfo.key(선택) 로 data 파라미터에 정의된 데이터에서 추출할 키값을 설정할 수 있어야 합니다.",
        "dcInfo.key(선택) 를 생략하면 dcInfo.id 값이 키로 사용되어야 합니다.",
        "dcInfo.action(선택) 을 생략(기본값 undefined)하면 기존 데이터를 data 파라미터의 데이터로 덮어써야 합니다.",
        "dcInfo.action 이 'append' 인 경우 기존 데이터에 data 파라미터의 데이터가 추가되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.resetData();
};

// 케이스 실행 전 데이터 초기화 (기존 1행만 남김)
scwin.resetData = function () {
    dlt_exam.removeAll();
    dlt_exam.insertRow(0);
    dlt_exam.setCellData(0, "code", "ORG01");
    dlt_exam.setCellData(0, "label", "ORIGIN");
    dlt_exam.reform();

    dma_exam.set("lang", "ko");
    dma_exam.set("output", "WebSquare");
    dma_exam.reform();
};



scwin.put = function (msg) {
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};

scwin.verify = function (label, actual, expected) {
    var pass = (String(actual) === String(expected));
    scwin.put("    [" + (pass ? "✓ PASS" : "✗ FAIL") + "] " + label + " = '" + actual + "'" + (pass ? "" : " (기대: '" + expected + "')"));
    return pass;
};

scwin.printResult = function (title, ok) {
    scwin.put(ok ? "결과 : " + title + " 정상 동작 확인" : "결과 : " + title + " 검증 불일치");
    scwin.put("");
};



scwin.btn_set_onclick = function () {
    var s = par_scenario.getValue();

    if (s === "1") {
        scwin.resetData();
        scwin.put("══ 시나리오 1 : dataType='JSON' + dcInfo 생략 (data 키 자동 매핑) ══");
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "C0001", "label" : "TYPE1" },
                { "code" : "C0002", "label" : "TYPE2" }
            ],
            "dma_exam" : { "lang" : "en", "output" : "JSON_SET" },
            "undefined_data" : { "code" : "X", "label" : "X" }
        });
        // 할당 결과 확인 ($p.data.get 활용)
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam.length (덮어쓰기 후 행 수)", ret.dlt_exam.length, 2);
        var p2 = scwin.verify("dlt_exam[0].code", ret.dlt_exam[0].code, "C0001");
        var p3 = scwin.verify("dlt_exam[1].label", ret.dlt_exam[1].label, "TYPE2");
        var p4 = scwin.verify("dma_exam.lang", ret.dma_exam.lang, "en");
        var p5 = scwin.verify("dma_exam.output", ret.dma_exam.output, "JSON_SET");
        // undefined_data 는 무시 → 신규 객체 생성되지 않음
        var p6 = scwin.verify("undefined_data 컴포넌트 미생성 (무시됨)", $p.getComponentById("undefined_data") ? "exist" : "null", "null");
        scwin.printResult("dataType='JSON' + dcInfo 생략 (자동 매핑)", p1 && p2 && p3 && p4 && p5 && p6);
    } else if (s === "2") {
        scwin.resetData();
        scwin.put("══ 시나리오 2 : dataType='ARRAY' + dcInfo 생략 ══");
        $p.data.set("ARRAY", {
            "dlt_exam" : {
                "columnInfo" : ["code", "label"],
                "data" : ["A0001", "ARR_LBL1", "A0002", "ARR_LBL2"]
            },
            "dma_exam" : ["ja", "ARRAY_SET"]
        });
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam.length", ret.dlt_exam.length, 2);
        var p2 = scwin.verify("dlt_exam[0].code", ret.dlt_exam[0].code, "A0001");
        var p3 = scwin.verify("dlt_exam[1].label", ret.dlt_exam[1].label, "ARR_LBL2");
        var p4 = scwin.verify("dma_exam.lang", ret.dma_exam.lang, "ja");
        var p5 = scwin.verify("dma_exam.output", ret.dma_exam.output, "ARRAY_SET");
        scwin.printResult("dataType='ARRAY' + dcInfo 생략", p1 && p2 && p3 && p4 && p5);
    } else if (s === "3") {
        scwin.resetData();
        scwin.put("══ 시나리오 3 : dataType='XML' + dcInfo 생략 (undefined_data 무시) ══");
        var strXml = '' +
            '<map>' +
            '    <list id=\'dlt_exam\'>' +
            '        <map><code>X0001</code><label>XML_LBL1</label></map>' +
            '        <map><code>X0002</code><label>XML_LBL2</label></map>' +
            '    </list>' +
            '    <map id=\'dma_exam\'>' +
            '        <lang>zh</lang>' +
            '        <output>XML_SET</output>' +
            '    </map>' +
            '    <map id=\'undefined_data\'>' +
            '        <code>X</code><label>X</label>' +
            '    </map>' +
            '</map>';
        $p.data.set("XML", WebSquare.xml.parse(strXml));
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam.length", ret.dlt_exam.length, 2);
        var p2 = scwin.verify("dlt_exam[0].code", ret.dlt_exam[0].code, "X0001");
        var p3 = scwin.verify("dlt_exam[1].label", ret.dlt_exam[1].label, "XML_LBL2");
        var p4 = scwin.verify("dma_exam.lang", ret.dma_exam.lang, "zh");
        var p5 = scwin.verify("dma_exam.output", ret.dma_exam.output, "XML_SET");
        var p6 = scwin.verify("undefined_data 컴포넌트 미생성 (무시됨)", $p.getComponentById("undefined_data") ? "exist" : "null", "null");
        scwin.printResult("dataType='XML' + dcInfo 생략", p1 && p2 && p3 && p4 && p5 && p6);
    } else if (s === "4") {
        scwin.resetData();
        scwin.put("══ 시나리오 4 : dcInfo 를 ID 배열로 설정 (할당 대상 제한) ══");
        // dlt_exam 만 dcInfo 에 포함 → dma_exam 은 data 에 있어도 할당 대상 제외
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "L0001", "label" : "LIMITED1" }
            ],
            "dma_exam" : { "lang" : "skipped", "output" : "skipped" }
        }, ["dlt_exam"]);
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam.length (할당됨)", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("dlt_exam[0].code", ret.dlt_exam[0].code, "L0001");
        // dma_exam 은 dcInfo 미포함 → 초기값 유지
        var p3 = scwin.verify("dma_exam.lang (제외 → 초기값 유지)", ret.dma_exam.lang, "ko");
        var p4 = scwin.verify("dma_exam.output (제외 → 초기값 유지)", ret.dma_exam.output, "WebSquare");
        scwin.printResult("dcInfo ID 배열 (할당 대상 제한)", p1 && p2 && p3 && p4);
    } else if (s === "5") {
        scwin.resetData();
        scwin.put("══ 시나리오 5 : dcInfo 객체 배열 ({id, key}) - key 매핑 ══");
        // user_dataMap 데이터를 dma_exam 에 할당 (key 매핑)
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "K0001", "label" : "KEY_MAPPED" }
            ],
            "user_dataMap" : { "lang" : "fr", "output" : "KEY_MAPPED_OUTPUT" }
        }, [
            { "id" : "dma_exam", "key" : "user_dataMap" },
            "dlt_exam"
        ]);
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam[0].code (id 만 사용)", ret.dlt_exam[0].code, "K0001");
        var p2 = scwin.verify("dma_exam.lang (user_dataMap 키 매핑)", ret.dma_exam.lang, "fr");
        var p3 = scwin.verify("dma_exam.output", ret.dma_exam.output, "KEY_MAPPED_OUTPUT");
        scwin.printResult("dcInfo 객체 배열 ({id, key} 키 매핑)", p1 && p2 && p3);
    } else if (s === "6") {
        scwin.resetData();
        scwin.put("══ 시나리오 6 : dcInfo.action='append' (기존 데이터에 추가) ══");
        // 기존 1행 (ORG01/ORIGIN) + append 2행 → 총 3행
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "AP001", "label" : "APPEND1" },
                { "code" : "AP002", "label" : "APPEND2" }
            ]
        }, [
            { "id" : "dlt_exam", "action" : "append" }
        ]);
        var ret = $p.data.get("JSON", ["dlt_exam"]);
        var p1 = scwin.verify("dlt_exam.length (기존 1 + 추가 2 = 3)", ret.dlt_exam.length, 3);
        var p2 = scwin.verify("dlt_exam[0].code (기존 데이터 유지)", ret.dlt_exam[0].code, "ORG01");
        var p3 = scwin.verify("dlt_exam[1].code (추가된 첫 행)", ret.dlt_exam[1].code, "AP001");
        var p4 = scwin.verify("dlt_exam[2].label (추가된 둘째 행)", ret.dlt_exam[2].label, "APPEND2");
        scwin.printResult("dcInfo.action='append' (추가)", p1 && p2 && p3 && p4);
    } else if (s === "7") {
        scwin.resetData();
        scwin.put("══ 시나리오 7 : dcInfo.action 생략 (기본값 → 덮어쓰기) ══");
        // 기존 1행이 모두 사라지고 신규 1행으로 덮어써야 함
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "OW001", "label" : "OVERWRITE" }
            ]
        }, [
            { "id" : "dlt_exam" }
        ]);
        var ret = $p.data.get("JSON", ["dlt_exam"]);
        var p1 = scwin.verify("dlt_exam.length (덮어쓰기 → 1)", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("dlt_exam[0].code (신규 행으로 교체)", ret.dlt_exam[0].code, "OW001");
        var p3 = scwin.verify("dlt_exam[0].label", ret.dlt_exam[0].label, "OVERWRITE");
        scwin.printResult("dcInfo.action 생략 (기본 덮어쓰기)", p1 && p2 && p3);
    } else if (s === "8") {
        scwin.resetData();
        scwin.put("══ 시나리오 8 : LinkedDataList 직접 할당 제외 → 원본 DataList 사용 ══");
        // ldl_exam 은 dlt_exam 을 bind. data 키로 'ldl_exam' 을 주면 무시되며,
        // 'dlt_exam' 으로 줘야 LinkedDataList 도 동기화됨.
        $p.data.set("JSON", {
            "ldl_exam" : [{ "code" : "IGN", "label" : "IGNORED" }],
            "dlt_exam" : [
                { "code" : "LK001", "label" : "LINKED1" },
                { "code" : "LK002", "label" : "LINKED2" }
            ]
        });
        var ret = $p.data.get("JSON", ["dlt_exam"]);
        var p1 = scwin.verify("원본 dlt_exam.length", ret.dlt_exam.length, 2);
        var p2 = scwin.verify("원본 dlt_exam[0].code", ret.dlt_exam[0].code, "LK001");
        // LinkedDataList 도 원본을 따라 동일하게 동기화
        var p3 = scwin.verify("ldl_exam.getRowCount() (원본과 동기)", ldl_exam.getRowCount(), 2);
        var p4 = scwin.verify("ldl_exam.getCellData(0,'code')", ldl_exam.getCellData(0, "code"), "LK001");
        // ldl_exam 키로 직접 할당된 'IGN' 데이터는 dlt_exam 에 반영되지 않아야 함
        var p5 = scwin.verify("dlt_exam[0].code 가 'IGN' 이 아님 (LinkedDataList 직접 할당 제외)", (ret.dlt_exam[0].code !== "IGN") ? "true" : "false", "true");
        scwin.printResult("LinkedDataList 직접 할당 제외 (원본 사용)", p1 && p2 && p3 && p4 && p5);
    } else if (s === "9") {
        scwin.resetData();
        scwin.put("══ 시나리오 9 : DataList + DataMap 동시 할당 (다건) ══");
        $p.data.set("JSON", {
            "dlt_exam" : [
                { "code" : "M0001", "label" : "MULTI1" },
                { "code" : "M0002", "label" : "MULTI2" },
                { "code" : "M0003", "label" : "MULTI3" }
            ],
            "dma_exam" : { "lang" : "de", "output" : "MULTI_SET" }
        }, ["dlt_exam", "dma_exam"]);
        var ret = $p.data.get("JSON", ["dlt_exam", "dma_exam"]);
        var p1 = scwin.verify("dlt_exam.length", ret.dlt_exam.length, 3);
        var p2 = scwin.verify("dlt_exam[2].label", ret.dlt_exam[2].label, "MULTI3");
        var p3 = scwin.verify("dma_exam.lang", ret.dma_exam.lang, "de");
        var p4 = scwin.verify("dma_exam.output", ret.dma_exam.output, "MULTI_SET");
        scwin.printResult("DataList + DataMap 동시 할당", p1 && p2 && p3 && p4);
    }
};
